export function hydrateImdbTitle(title) {
  if (!title) return null;
  const rating = title.rating ?? {};
  const meta = title.metacritic ?? {};
  const primary = title.primaryImage ?? {};
  return {
    imdbId: title.id,
    type: title.type,
    title: title.primaryTitle,
    originalTitle: title.originalTitle,
    year: title.startYear ?? null,
    endYear: title.endYear ?? null,
    runtimeMinutes: title.runtimeSeconds != null ? Math.round(title.runtimeSeconds / 60) : null,
    genres: title.genres ?? [],
    posterUrl: primary.url ?? null,
    posterWidth: primary.width ?? null,
    posterHeight: primary.height ?? null,
    imdbRating: rating.aggregateRating ?? null,
    imdbVotes: rating.voteCount ?? null,
    metascore: meta.metascore ?? null,
    plot: title.plot ?? null,
    interestTags: (title.interests ?? []).map(i => ({ id: i.id, name: i.name })),
    directors: (title.directors ?? []).map(n => ({ id: n.id, name: n.displayName ?? n.name })),
    writers: (title.writers ?? []).map(n => ({ id: n.id, name: n.displayName ?? n.name })),
    stars: (title.stars ?? []).map(n => ({ id: n.id, name: n.displayName ?? n.name })),
    originCountries: (title.originCountries ?? []).map(c => ({ code: c.code, name: c.name })),
    spokenLanguages: (title.spokenLanguages ?? []).map(l => ({ code: l.code, name: l.name })),
    imdbUrl: title.id ? `https://www.imdb.com/title/${title.id}/` : null
  };
}

export async function findNameCandidates(query, limit = 3) {
  const titles = await searchTitles(query, 5);
  const nameHits = new Map();
  const q = query.toLowerCase();
  for (const t of titles) {
    for (const group of [t.directors, t.writers, t.stars]) {
      for (const n of group ?? []) {
        if (!n?.id) continue;
        if (n.name && n.name.toLowerCase().includes(q)) {
          if (!nameHits.has(n.id)) nameHits.set(n.id, { ...n, titleHits: [] });
          nameHits.get(n.id).titleHits.push(t.title);
        }
      }
    }
  }
  if (nameHits.size < limit) {
    for (const t of titles.slice(0, 2)) {
      try {
        const credits = await getCredits(t.imdbId, { pageSize: 30 });
        for (const c of credits.credits ?? credits.results ?? []) {
          const person = c.name ?? {};
          if (!person.id) continue;
          const personName = person.displayName ?? person.name ?? '';
          if (personName.toLowerCase().includes(q) && !nameHits.has(person.id)) {
            nameHits.set(person.id, {
              id: person.id,
              name: personName,
              titleHits: [t.title]
            });
          }
        }
      } catch { /* continue */ }
    }
  }
  return Array.from(nameHits.values()).slice(0, limit);
}

import { MovieDb } from 'moviedb-promise';
import { getApiKey } from './config.js';

let cached = null;

export async function getClient() {
  const key = await getApiKey();
  if (!key) {
    throw new Error('TMDB API key not configured. Run the `setup` skill in Claude Code, or set TMDB_API_KEY.');
  }
  if (!cached || cached.key !== key) {
    cached = { key, client: new MovieDb(key), imageConfig: null, genres: null };
  }
  return cached.client;
}

async function getImageConfig() {
  if (cached?.imageConfig) return cached.imageConfig;
  const client = await getClient();
  const result = await client.configuration();
  cached.imageConfig = result.images;
  return cached.imageConfig;
}

function imageUrl(cfg, path, size) {
  return path ? `${cfg.secure_base_url}${size}${path}` : null;
}

export async function hydrateMovie(movie, imdbPartial) {
  const cfg = await getImageConfig();
  const base = {
    id: movie.id,
    title: movie.title ?? movie.name,
    originalTitle: movie.original_title ?? movie.original_name,
    year: movie.release_date ? movie.release_date.slice(0, 4) : null,
    releaseDate: movie.release_date,
    overview: movie.overview,
    rating: movie.vote_average,
    voteCount: movie.vote_count,
    popularity: movie.popularity,
    genreIds: movie.genre_ids,
    genres: movie.genres?.map(g => g.name),
    runtime: movie.runtime,
    posterUrl: imageUrl(cfg, movie.poster_path, 'w500'),
    backdropUrl: imageUrl(cfg, movie.backdrop_path, 'w1280'),
    tmdbUrl: `https://www.themoviedb.org/movie/${movie.id}`
  };
  if (imdbPartial) {
    if (imdbPartial.imdbRating != null) base.imdbRating = imdbPartial.imdbRating;
    if (imdbPartial.imdbVotes != null) base.imdbVotes = imdbPartial.imdbVotes;
    if (imdbPartial.metascore != null) base.metascore = imdbPartial.metascore;
    if (imdbPartial.interestTags?.length) base.imdbInterestTags = imdbPartial.interestTags;
    if (imdbPartial.imdbId) base.imdbId = imdbPartial.imdbId;
  }
  return base;
}

export async function hydrateList(movies) {
  return Promise.all((movies ?? []).map(m => hydrateMovie(m)));
}

export function getGenreCache() { return cached?.genres ?? null; }
export function setGenreCache(genres) { if (cached) cached.genres = genres; }

import { getClient, getGenreCache, setGenreCache } from './tmdb.js';

export async function getGenres() {
  const cached = getGenreCache();
  if (cached) return cached;
  const client = await getClient();
  const result = await client.genreMovieList();
  setGenreCache(result.genres);
  return result.genres;
}

export async function resolveGenreIds(names) {
  if (!names?.length) return [];
  if (names.every(n => typeof n === 'number')) return names;
  const genres = await getGenres();
  const map = new Map(genres.map(g => [g.name.toLowerCase(), g.id]));
  return names
    .map(n => (typeof n === 'number' ? n : map.get(String(n).toLowerCase())))
    .filter(Boolean);
}

import fs from 'node:fs/promises';
import { paths, ensureDataDir } from './paths.js';

async function readJson(file, fallback) {
  try {
    return JSON.parse(await fs.readFile(file, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return fallback;
    throw err;
  }
}

async function writeJson(file, data) {
  await ensureDataDir();
  await fs.writeFile(file, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

const DEFAULT_PREFERENCES = {
  likedGenres: [],
